    """Return the integer value of an ASCII digit string, or None if invalid."""
    if not isinstance(raw, str) or not raw.isascii() or not raw.isdigit():
        return None
    try:
        return int(raw)
    except ValueError:
        # Python limits int(str) for very long strings; such a value is still
        # a valid digit string, so build it without the string conversion.
        value = 0
        for char in raw:
            value = value * 10 + (ord(char) - ord("0"))
        return value


